"use strict";(self.webpackChunk_711=self.webpackChunk_711||[]).push([[120],{120(n,e,a){a.r(e),a.d(e,{default:()=>l}),a.dn(l);var i=a(540);function l(){return i.createElement("div",{className:"markdown",dangerouslySetInnerHTML:{__html:'<style>\n.markdown h3, .markdown h4 {\n    margin: 0;\n}\n</style>\n\n<h1>Workshops Archive</h1>\n<p>See previous workshops we have hosted!</p>\n<p><a href="../">Click here to return to the list of upcoming workshops.</a></p>\n<hr>\n<h1><a href="https://www.sfgoodneighborweek.org/">Good Neighbor Week</a>: Ingleside</h1>\n<h2>Saturday, 26 September, 8:00am-3:00pm</h2>\n<p>Join your Ingleside neighbors in kicking off <a href="https://www.sfgoodneighborweek.org/">Good Neighbor Week</a> with a\nfull day of neighborhood beautification work!</p>\n<ul>\n<li>8:00am-10:00am: Weeding near Balboa Park BART<ul>\n<li>Meet in the <a href="https://maps.app.goo.gl/9MJDxLD6YXpP7Wpt9">BART plaza (outside 402 Geneva Ave)</a></li>\n<li>Bring gloves, plant clippers, etc.</li>\n</ul>\n</li>\n<li>11:00am-12:00pm: Trash pickup<ul>\n<li>Meet at [Ocean Ale House][oah-maps]</li>\n<li>All supplies provided, including lunch afterwards!</li>\n</ul>\n</li>\n<li>2:00pm-3:00pm: Cigarette butt mitigation<ul>\n<li>Meet at <a href="https://maps.app.goo.gl/PgVsZ9DDPVzkRJ1F6">Unity Plaza</a></li>\n<li>Bring brooms and bags; we will have some too.</li>\n<li>Where feasible, we will try to hang cigarette butt disposal cans.</li>\n</ul>\n</li>\n</ul>\n<hr>\n<h3>Plant swap</h3>\n<h4>September 12 | 10:30am-11:30am</h4>\n<p>Thanks to <a href="https://sfpl.org/events/2026/09/12/social-plant-swap">San Francisco Public Library</a> for running this\nevent!<br><strong>September 12&#39;s plant swap was hosted at Unity Plaza.</strong></p>\n<p>Bring your cuttings, seedlings, surplus harvest, or plants that need a new home\nto swap with other gardeners.</p>\n<p>All types of plants welcome; please label if possible.</p>\n<p>Thanks to <a href="https://alemanyfarm.org/">Friends of Alemany Farms</a> for giving away plant\nstarters!</p>\n<hr>\n<h3>Disaster readiness</h3>\n<h4>@ SFPL Ingleside</h4>\n<h4>August 22 | 2pm-3pm</h4>\n<p><strong>NOTE: This event was hosted at</strong>:<br />\nIngleside Branch Library, 1298 Ocean Avenue<br />\nThis is not a Library sponsored program.</p>\n<ul>\n<li>making a disaster plan</li>\n<li>what to do in an earthquake</li>\n<li>preparing your family and home</li>\n</ul>\n<hr>\n<h3>Bike repair</h3>\n<h4>August 15 | 2pm-3pm</h4>\n<ul>\n<li>how to fix a flat tire</li>\n<li>how to clean and grease the chain</li>\n<li>how to make simple adjustments</li>\n</ul>\n<hr>\n<h3>Car maintenance</h3>\n<h4>August 8 | 2pm-3pm</h4>\n<ul>\n<li>how cars work, in brief</li>\n<li>how to use mechanics&#39; hand tools</li>\n<li>survival skills: jumpstarts, flat tires</li>\n</ul>\n<hr>\n<h3>Mural painting</h3>\n<h4>July 25 | 2:30pm-3:30pm</h4>\n<ul>\n<li>what&#39;s different about painting outdoors</li>\n<li>how to paint a house mural</li>\n</ul>\n<hr>\n<h3>Car maintenance</h3>\n<h4>July 11 | 2:30pm-3:30pm</h4>\n<ul>\n<li>how cars work, in brief</li>\n<li>how to use mechanics&#39; hand tools</li>\n<li>how to change your engine oil</li>\n</ul>\n<hr>\n<h3>Bike repair</h3>\n<h4>June 20 | 2:30pm-3:30pm</h4>\n<ul>\n<li>how to fix a flat tire</li>\n<li>how to clean and grease the chain</li>\n<li>how to make simple adjustments</li>\n</ul>\n'}})}}}]);
